const tasksForRun = `-- name: TasksForRun :many
SELECT id, sequence_id, action, payload, time_offset, continue_on_failure
FROM tasks
WHERE schedule_id = ?
ORDER BY sequence_id, id
`

type TasksForRunRow struct {
	ID                uint32
	SequenceID        uint32
	Action            string
	Payload           string
	TimeOffset        uint32
	ContinueOnFailure uint8
}

func (q *Queries) TasksForRun(ctx context.Context, scheduleID uint32) ([]TasksForRunRow, error) {
	rows, err := q.db.QueryContext(ctx, tasksForRun, scheduleID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TasksForRunRow
	for rows.Next() {
		var i TasksForRunRow
		if err := rows.Scan(
			&i.ID,
			&i.SequenceID,
			&i.Action,
			&i.Payload,
			&i.TimeOffset,
			&i.ContinueOnFailure,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

